# tiles: 2x2 square -> all color 1; L-triomino (2x2 missing one corner) -> color by missing corner
# missing TL->2, BL->3, TR->4, BR->5 (hypothesis)
def cells(g): return {(r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==8}

def tilings(C):
    if not C: yield []; return
    r,c = min(C)
    opts=[]
    # 2x2 square with (r,c) as TL or other corners
    for dr in (0,-1):
        for dc in (0,-1):
            blk={(r+dr+a,c+dc+b) for a in range(2) for b in range(2)}
            if blk<=C: opts.append(('sq',blk,dr,dc))
    if opts:  # try squares
        for name,blk,dr,dc in opts:
            for rest in tilings(C-blk): yield [('sq',blk)]+rest
    # L triominoes: 2x2 minus one corner
    for dr in (0,-1):
        for dc in (0,-1):
            blk={(r+dr+a,c+dc+b) for a in range(2) for b in range(2)}
            if blk<=C:
                for miss in blk:
                    tri=blk-{miss}
                    for rest in tilings(C-tri): yield [('L',tri,frozenset({miss}))]+rest

mis = {(0,0):'TL',(1,0):'BL',(0,1):'TR',(1,1):'BR'}
def color_tiling(t,C):
    out=[[0]*len(C and 7 or 7) for _ in range(7)]
    g=[[0]*7 for _ in range(7)]
    for name,blk,*rest in t:
        if name=='sq':
            for r,c in blk: g[r][c]=1
        else:
            miss=rest[0]; m=min(miss); # relative
            # determine which corner relative to block
            rs=[r for r,c in blk]; cs=[c for r,c in blk]
            mr,mc=min(rs),min(cs)
            pos=mis[(m[0]-mr,m[1]-mc)]
            col={'TL':2,'BL':3,'TR':4,'BR':5}[pos]
            for r,c in blk-{m}: g[r][c]=col
    return g

